function validate([matrix, k]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 100) return 'matrix needs 1 to 100 rows.';
  const n = matrix[0].length;
  if (n < 1 || n > 100) return 'Each row needs 1 to 100 columns.';
  if (matrix.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (matrix.some(row => row.some(v => !Number.isInteger(v) || v < -100 || v > 100))) return 'Each cell is an integer between -100 and 100.';
  if (!Number.isInteger(k) || k < -100000 || k > 100000) return 'k is between -10^5 and 10^5.';
  // The smallest rectangle sum (over column ranges, Kadane on rows) must be at most k.
  let least = Infinity;
  for (let left = 0; left < n; left++) {
    const sums = new Array(matrix.length).fill(0);
    for (let right = left; right < n; right++) {
      let run = Infinity;
      for (let r = 0; r < matrix.length; r++) {
        sums[r] += matrix[r][right];
        run = Math.min(sums[r], run + sums[r]);
        least = Math.min(least, run);
      }
    }
  }
  if (least > k) return 'Some rectangle must have a sum of at most k.';
  return null;
}

