function maxSumSubmatrix(matrix, k) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  let best = -Infinity;

  for (let left = 0; left < cols; left++) {
    const rowSums = new Array(rows).fill(0);
    for (let right = left; right < cols; right++) {
      for (let r = 0; r < rows; r++) {
        rowSums[r] += matrix[r][right];
      }
      const seen = [0];
      let prefix = 0;
      for (const value of rowSums) {
        prefix += value;
        const index = lowerBound(seen, prefix - k);
        if (index < seen.length) {
          best = Math.max(best, prefix - seen[index]);
        }
        seen.splice(lowerBound(seen, prefix), 0, prefix);
      }
      if (best === k) {
        return k;
      }
    }
  }
  return best;

  function lowerBound(sorted, target) {
    let lo = 0;
    let hi = sorted.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (sorted[mid] < target) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }
}

