function maxSumSubmatrix(matrix, k) {
  const m = matrix.length, n = matrix[0].length;
  const P = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
  for (let i = 0; i < m; i++)
    for (let j = 0; j < n; j++)
      P[i + 1][j + 1] = matrix[i][j] + P[i][j + 1] + P[i + 1][j] - P[i][j];
  let answer = null;
  for (let r1 = 0; r1 < m; r1++)
    for (let r2 = r1; r2 < m; r2++)
      for (let c1 = 0; c1 < n; c1++)
        for (let c2 = c1; c2 < n; c2++) {
          const total = P[r2 + 1][c2 + 1] - P[r1][c2 + 1] - P[r2 + 1][c1] + P[r1][c1];
          if (total <= k && (answer === null || total > answer)) answer = total;
        }
  return answer;
}

