function generate(rand, size) {
  const m = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 4);
  const span = size === 'large' ? 100 : 6;
  const matrix = Array.from({ length: m }, () => Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span));
  // The smallest cell is a rectangle, so any k at or above it keeps the guarantee.
  const low = Math.min(...matrix.flat());
  const reach = size === 'large' ? 3000 : 20;
  const k = Math.min(100000, low + Math.floor(rand() * reach));
  return [matrix, k];
}
